<?php
require __DIR__.'/_init.php';
$statuses=['pending'=>'در انتظار بررسی','processing'=>'در حال آماده‌سازی','shipped'=>'ارسال شده','completed'=>'تکمیل شده','cancelled'=>'لغو شده'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'pending');if(isset($statuses[$status])){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);flash('success','وضعیت سفارش به‌روزرسانی شد.');}header('Location: '.site_url('admin/orders.php'));exit;}
$orders=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 300')->fetchAll();
render_header('مدیریت سفارش‌ها');
?><main class="container"><div class="page-title"><h1>مدیریت سفارش‌ها</h1><p>آخرین ۳۰۰ سفارش ثبت‌شده.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/logout.php'))?>">خروج</a></aside><section class="admin-content"><div class="table-wrap"><table class="table"><thead><tr><th>کد</th><th>مشتری</th><th>تلفن</th><th>مبلغ</th><th>پرداخت</th><th>فایل طرح</th><th>وضعیت سفارش</th><th>تاریخ</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e(substr($o['public_code'],0,8))?>…</td><td><?=e($o['customer_name'])?></td><td><?=e($o['phone'])?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['payment_status']==='unpaid'?'پرداخت نشده':$o['payment_status'])?></td><td><?php $fq=$pdo->prepare('SELECT id,original_name FROM order_files WHERE order_id=?');$fq->execute([$o['id']]);foreach($fq->fetchAll() as $file): ?><a href="<?=e(site_url('admin/download-design.php?id='.$file['id']))?>">دانلود <?=e($file['original_name'])?></a><br><?php endforeach;?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($statuses as $key=>$label): ?><option value="<?=e($key)?>" <?=$o['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select><button class="small-btn">ذخیره</button></form></td><td><?=e($o['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></section></div></main><?php render_footer(); ?>
